const prisma = new PrismaClient();

async function seedQuestions() {
  // The database enforces Category.name as unique. The category may already exist
  // under a different slug, so resolve by slug first and then by name.
  let category = await prisma.category.findUnique({
    where: { slug: CATEGORY_SLUG },
  });

  if (category) {
    category = await prisma.category.update({
      where: { id: category.id },
      data: { name: CATEGORY_NAME, group: "Technology" },
    });
  } else {
    category = await prisma.category.findUnique({
      where: { name: CATEGORY_NAME },
    });

    if (category) {
      category = await prisma.category.update({
        where: { id: category.id },
        data: { group: "Technology" },
      });
    } else {
      category = await prisma.category.create({
        data: {
          name: CATEGORY_NAME,
          slug: CATEGORY_SLUG,
          group: "Technology",
        },
      });
    }
  }

  const subcategory = await prisma.subcategory.upsert({
    where: { categoryId_slug: { categoryId: category.id, slug: SUBCATEGORY_SLUG } },
    update: { name: SUBCATEGORY_NAME },
    create: { name: SUBCATEGORY_NAME, slug: SUBCATEGORY_SLUG, categoryId: category.id },
  });

  for (const item of questions) {
    // These are content/display fields from the seed format, not columns on
    // InterviewQuestion in the current Prisma schema. Remove them before the
    // Prisma write while retaining the actual category/subcategory IDs.
    const {
      categoryName,
      categorySlug,
      subcategoryName,
      subcategorySlug,
      ...questionData
    } = item;

    const question = await prisma.interviewQuestion.upsert({
      where: { slug: item.slug },
      update: {
        ...questionData,
        categoryId: category.id,
        subcategoryId: subcategory.id,
        isPublished: true,
      },
      create: {
        ...questionData,
        categoryId: category.id,
        subcategoryId: subcategory.id,
        isPublished: true,
      },
    });
    console.log(`${question.id}: ${question.question}`);
  }

  console.log(`Seeded ${questions.length} DSA interview questions.`);
}

seedQuestions()
  .catch((error) => {
    console.error("Failed to seed interview questions:", error);
    process.exitCode = 1;
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
